function encode(strs) {
  let out = "";
  // Length-prefix is delimiter-safe — payload may contain '#' itself.
  for (const s of strs) out += s.length + "#" + s;
  return out;
}
function decode(str) {
  const res = [];
  let i = 0;
  while (i < str.length) {
    let j = i;
    // Scan (don't split) — payload may contain '#'.
    while (str[j] !== "#") j++;
    const len = Number(str.slice(i, j));
    res.push(str.slice(j + 1, j + 1 + len));
    // Jump past '#' (1) + payload (len) to land on next header.
    i = j + 1 + len;
  }
  return res;
}
const enc = encode(["hello", "world"]);
console.log(enc);
console.log(JSON.stringify(decode(enc)));
